import{_ as t,o,c as r,a3 as a}from"./chunks/framework.CfYLvWnO.js";const g=JSON.parse('{"title":"Interceptor writer","description":"","frontmatter":{"order":30},"headers":[],"relativePath":"writing/interceptor.md","filePath":"writing/interceptor.md"}'),i={name:"writing/interceptor.md"};function n(s,e,d,c,h,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="interceptor-writer" tabindex="-1">Interceptor writer <a class="header-anchor" href="#interceptor-writer" aria-label="Permalink to &quot;Interceptor writer&quot;">​</a></h1><p><code>HistoryWriter.Interceptor</code> writes history from a <code>SaveChangesInterceptor</code> in your application, in the same transaction as the change. It is the default writer. Use it where the role that applies migrations cannot create functions and triggers; otherwise prefer the <a href="/hindsight-efcore/1.2/writing/trigger">trigger writer</a>.</p><div class="warning custom-block"><p class="custom-block-title">It only sees <code>SaveChanges</code></p><p><code>ExecuteUpdate</code>, <code>ExecuteDelete</code>, writes through <code>FromSql</code> or <code>SqlQuery</code>, and changes made by other processes never reach a <code>SaveChangesInterceptor</code>. They write <strong>no history</strong> under this writer.</p></div><h2 id="how-a-savechanges-is-recorded" tabindex="-1">How a <code>SaveChanges</code> is recorded <a class="header-anchor" href="#how-a-savechanges-is-recorded" aria-label="Permalink to &quot;How a `SaveChanges` is recorded&quot;">​</a></h2><ol><li><p><strong>Before the save</strong>, the interceptor snapshots every temporal entity that is <code>Added</code>, <code>Modified</code> or <code>Deleted</code>, and drops any <code>Modified</code> entity whose only changes are to <a href="/hindsight-efcore/1.2/configuration/temporal-entities#excluding-properties">excluded</a> properties. It takes one timestamp from <code>TimeProvider</code> for the whole save, and opens a transaction if you have none (see <a href="/hindsight-efcore/1.2/writing/transactions">Transactions</a>).</p><p>For each <code>Deleted</code> entity it re-reads the row from the database by key (<code>SELECT … FOR UPDATE</code>). An entity deleted without being loaded first, such as <code>Remove(new Policy { Id = id, … })</code>, only holds default values, and those must not end up in the tombstone. If the row no longer exists, the save throws <code>InvalidOperationException</code>.</p></li><li><p><strong>The save runs</strong> as usual.</p></li><li><p><strong>After the save</strong>, when store-generated keys are known, it writes history for every entity in a single batched round trip (split every 512 rows):</p><ul><li><code>Added</code>: inserts an open version;</li><li><code>Modified</code>: closes the open version and inserts the new one;</li><li><code>Deleted</code>: closes the open version and inserts a tombstone.</li></ul></li><li><p>It commits the transaction if it opened it.</p></li></ol><p>The open version is closed at <code>GREATEST(@timestamp, valid_from + interval &#39;1 microsecond&#39;)</code>, the same clamp as the trigger writer. A save that captured its timestamp and then waited for a row lock, or a clock that stepped backwards, still produces a contiguous chain of positive periods. In exactly those cases, the new version starts slightly later than the time <code>TimeProvider</code> reported.</p><p>Values are sent as parameters with each column&#39;s own type mapping, so an enum stored as text, a <code>jsonb</code> column or a <code>numeric(18,4)</code> column lands in history exactly as in the main table.</p><h2 id="if-the-history-write-fails" tabindex="-1">If the history write fails <a class="header-anchor" href="#if-the-history-write-fails" aria-label="Permalink to &quot;If the history write fails {#if-the-history-write-fails}&quot;">​</a></h2><p>The history is written after EF Core has sent the change <em>and</em> accepted it in the change tracker. If the history write then fails, for example because of invalid JSON in <code>ChangeContext.Extra</code> or a dropped connection:</p><ul><li><strong>The database is always correct.</strong> The interceptor rolls back its transaction, so neither the change nor its history is stored.</li><li><strong><code>Added</code> and <code>Modified</code> entities are restored</strong> to their state before the save, so catching the exception and calling <code>SaveChanges</code> again retries the whole change.</li><li><strong><code>Deleted</code> entities stay detached.</strong> EF Core has already removed them from the change tracker, so a retry does nothing for them. Query the entity again and remove it again.</li><li><strong>An <code>Added</code> entity with a store-generated key keeps the key</strong> it received in the rolled-back transaction. See <a href="/hindsight-efcore/1.2/reference/limitations#known-trade-offs">Limitations</a> for what a retry does with it.</li></ul><p>The trigger writer does not have this gap: its history is written in the same statement as the change.</p><h2 id="your-own-interceptors-run-after-hindsights" tabindex="-1">Your own interceptors run after Hindsight&#39;s <a class="header-anchor" href="#your-own-interceptors-run-after-hindsights" aria-label="Permalink to &quot;Your own interceptors run after Hindsight&#39;s {#your-own-interceptors-run-after-hindsights}&quot;">​</a></h2><p>A <code>SaveChangesInterceptor</code> you add with <code>AddInterceptors(...)</code> always runs <strong>after</strong> Hindsight&#39;s, no matter where it appears relative to <code>UseHindsight(...)</code>. That is EF Core&#39;s ordering, not a setting.</p><p>So if your interceptor changes an entity&#39;s state inside <code>SavingChanges</code>, for example an audit stamp that flips an <code>Unchanged</code> entity to <code>Modified</code>, Hindsight has already taken its snapshot. The update reaches the main table, but <strong>no version is written</strong> for it, and no exception is thrown.</p><p>If you rely on such an interceptor, use the trigger writer: the trigger sees the <code>UPDATE</code> in the database, whoever caused it.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>About 1.7× to 3× the time of a plain <code>SaveChanges</code>, depending on the operation, and one extra round trip for a save that deletes a temporal entity. See the <a href="/hindsight-efcore/1.2/reference/benchmarks">benchmarks</a>.</p>',17)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
